    h = to_int(g.get("grid_height", g.get("height", 0)))

    s = pos(g.get("self_position", g.get("agent_position", g.get("position"))))
    o = pos(g.get("opponent_position", g.get("enemy_position", (10**9, 10**9))))

    resources = [pos(x) for x in seq(g.get("resources", g.get("resource_positions", [])))]
    obstacles = {pos(x) for x in seq(g.get("obstacles", g.get("walls", [])))}
    self_path = {pos(x) for x in seq(g.get("self_path", []))}
    opp_path = {pos(x) for x in seq(g.get("opponent_path", []))}
    territories = seq(g.get("territories", []))
    targets = [pos(x) for x in seq(g.get("targets", g.get("goal_positions", [])))]

    avoid = obstacles | self_path | opp_path

    def valid(p):
        return 0 <= p[0] < w and 0 <= p[1] < h and p not in obstacles

