    if resources:
        mode = "resource"
    if territories or "owned_territory" in g or "territory" in g:
        mode = "territory"
    if "health" in g or "enemy_health" in g or "opponent_health" in g:
        mode = "pursuit"

    def center():
        return (w // 2, h // 2)

    def nearest_score(p, pts):
        if not pts:
            return 0
        return min(dist(p, q) for q in pts)

